// `agentrun skill install`: this package's skill (skills/agentrun-cli, generated by scripts/generate-clients.mjs) copied
// into the skill folders of the coding agents on this machine, or into one named. Claude Code reads a person's skills from
// ~/.claude/skills (CLAUDE_CONFIG_DIR moves ~/.claude), Codex from $CODEX_HOME/skills (default ~/.codex/skills), where its
// own skill installer writes.
import { cpSync, existsSync, readFileSync, rmSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const NAME = "agentrun-cli";
const SOURCE = fileURLToPath(new URL(`../skills/${NAME}`, import.meta.url));

/** A folder this command may replace: none there yet, or this skill, by its front matter's name. */
const ours = (dir) => {
  if (!existsSync(dir)) return true;
  try {
    return /^---\n(?:.*\n)*?name: agentrun-cli\n/.test(readFileSync(join(dir, "SKILL.md"), "utf8"));
  } catch {
    return false;
  }
};

export const SKILL_INSTALL = {
  command: ["skill", "install"],
  pathParams: [],
  summary: "Install this CLI's skill (agentrun-cli) for Claude Code and Codex, or into a skills directory",
  help: [
    ["--claude", "into Claude Code's skills: ~/.claude/skills/agentrun-cli"],
    ["--codex", "into Codex's skills: $CODEX_HOME/skills/agentrun-cli (default ~/.codex/skills)"],
    ["--dir DIR", "into DIR/agentrun-cli (a project's .claude/skills or .agents/skills, say)"],
    ["", "with none of them: each of Claude Code and Codex that has its folder on this machine"],
  ],
  options: { claude: { type: "boolean" }, codex: { type: "boolean" }, dir: { type: "string" } },
  async run({ values, env, io, cli }) {
    const claude = join(env.CLAUDE_CONFIG_DIR || join(homedir(), ".claude"), "skills");
    const codex = join(env.CODEX_HOME || join(homedir(), ".codex"), "skills");
    const asked = [values.claude && claude, values.codex && codex, values.dir !== undefined && resolve(values.dir)].filter(Boolean);
    const dirs = asked.length ? asked : [claude, codex].filter((dir) => existsSync(join(dir, "..")));
    if (!dirs.length) throw cli.fail(2, `Neither ${join(claude, "..")} nor ${join(codex, "..")} exists: name where with --claude, --codex or --dir DIR.`);
    const installed = [];
    for (const dir of dirs) {
      const target = join(dir, NAME);
      if (!ours(target)) throw cli.fail(1, `${target} exists and is not this skill: move it, or install with --dir DIR.`);
      rmSync(target, { recursive: true, force: true });
      cpSync(SOURCE, target, { recursive: true });
      installed.push(target);
    }
    io.stdout.write(`${JSON.stringify({ installed })}\n`);
    return 0;
  },
};
